import 'fraction.dart';

// â”€â”€ Constants and LaTeX Helpers (local copies for yi_steps independence) â”€

const _oFrac = YIFraction(numerator: 1, denominator: 1);
const _noFrac = YIFraction(numerator: -1, denominator: 1);

String fracLatex(YIFraction f) {
  final s = f.simplified();
  if (s.denominator == 1) return '${s.numerator}';
  return s.numerator < 0
      ? '-\\frac{${s.numerator.abs()}}{${s.denominator}}'
      : '\\frac{${s.numerator}}{${s.denominator}}';
}

String boxLatex(String inner) => '\\boxed{$inner}';

String mxLatex(YIFraction m) {
  final s = m.simplified();
  if (s == _oFrac) return 'x';
  if (s == _noFrac) return '-x';
  return '${fracLatex(s)}x';
}

String eqLatex(YIFraction m, YIFraction b) {
  final ms = m.simplified(), bs = b.simplified();
  if (ms.isZero) return 'y = ${fracLatex(bs)}';
  final mp = mxLatex(ms);
  if (bs.isZero) return 'y = $mp';
  return bs.numerator > 0 ? 'y = $mp + ${fracLatex(bs)}' : 'y = $mp - ${fracLatex(bs.abs())}';
}

