// â”€â”€ Step Builders: Slope from Standard Form â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

List<YISolverStep> buildSlopeStepsFromStandard(
  int A, int B, int C,
  YIFraction m, YIFraction b,
  String sfTex, String gfTex, String eqTex,
) {
  final yOnly = B == 1 ? 'y' : B == -1 ? '-y' : '${B}y';
  return [
    YISolverStep.single(number: 1, title: 'Standard Form',
      formulaLatex: r'Ax + By = C',
      substitutionLatex: sfTex, resultLatex: sfTex,
      explanation: 'Start with the equation in standard form.'),
    YISolverStep.single(number: 2, title: 'Move x-term',
      formulaLatex: r'By = C - Ax',
      substitutionLatex: 'Move the x-term to the right',
      resultLatex: '$yOnly = $C ${A > 0 ? '-' : '+'} ${A.abs()}x',
      explanation: 'Subtract the x-term from both sides.'),
    YISolverStep.single(number: 3, title: 'Divide by $B',
      formulaLatex: r'y = mx + b',
      substitutionLatex: 'y = \\frac{${-A}}{$B}x + \\frac{$C}{$B}',
      resultLatex: eqTex,
      explanation: 'Divide every term by the coefficient of y.'),
    YISolverStep.dual(number: 4, title: 'Read m and b',
      leftLabel: 'Slope  m', rightLabel: 'y-intercept  b',
      leftLatex: 'm = \\boxed{${fracLatex(m)}}',
      rightLatex: 'b = \\boxed{${fracLatex(b)}}',
      resultLatex: 'm = ${fracLatex(m)}, \\quad b = ${fracLatex(b)}'),
  ];
}

// â”€â”€ Step Builders: Slope from General Form â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

List<YISolverStep> buildSlopeStepsFromGeneral(
  int A, int B, int C,
  YIFraction m, YIFraction b,
  String sfTex, String gfTex, String eqTex,
) {
  final sfFromGf = '${A}x ${B >= 0 ? '+' : '-'} ${B.abs()}y = $C';
  return [
    YISolverStep.single(number: 1, title: 'General Form',
      formulaLatex: r'Ax + By + C = 0',
      substitutionLatex: gfTex, resultLatex: gfTex,
      explanation: 'Start with the equation in general form.'),
    YISolverStep.single(number: 2, title: 'Convert to Standard Form',
      formulaLatex: r'Ax + By = -C',
      substitutionLatex: 'Move the constant to the right',
      resultLatex: sfFromGf,
      explanation: 'Move the constant term to the right side.'),
    YISolverStep.single(number: 3, title: 'Move x-term and divide by $B',
      formulaLatex: r'y = mx + b',
      substitutionLatex: 'y = \\frac{${-A}}{$B}x + \\frac{$C}{$B}',
      resultLatex: eqTex,
      explanation: 'Move x-term, then divide by $B.'),
    YISolverStep.dual(number: 4, title: 'Read m and b',
      leftLabel: 'Slope  m', rightLabel: 'y-intercept  b',
      leftLatex: 'm = \\boxed{${fracLatex(m)}}',
      rightLatex: 'b = \\boxed{${fracLatex(b)}}',
      resultLatex: 'm = ${fracLatex(m)}, \\quad b = ${fracLatex(b)}'),
  ];
}

